#!/bin/bash
# Uninstall script for Floorp browser
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Floorp browser..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Floorp browser if running..."
pkill -f "Floorp browser" 2>/dev/null || true

# Remove /Applications/Floorp.app
echo "Removing /Applications/Floorp.app..."
if [ -d "/Applications/Floorp.app" ]; then
    rm -rf "/Applications/Floorp.app" 2>/dev/null || true
elif [ -f "/Applications/Floorp.app" ]; then
    rm -f "/Applications/Floorp.app" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/Floorp
echo "Removing $HOME/Library/Application Support/Floorp..."
if [ -d "$HOME/Library/Application Support/Floorp" ]; then
    rm -rf "$HOME/Library/Application Support/Floorp" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/Floorp" ]; then
    rm -f "$HOME/Library/Application Support/Floorp" 2>/dev/null || true
fi

# Remove $HOME/Library/Caches/Floorp
echo "Removing $HOME/Library/Caches/Floorp..."
if [ -d "$HOME/Library/Caches/Floorp" ]; then
    rm -rf "$HOME/Library/Caches/Floorp" 2>/dev/null || true
elif [ -f "$HOME/Library/Caches/Floorp" ]; then
    rm -f "$HOME/Library/Caches/Floorp" 2>/dev/null || true
fi

# Remove $HOME/Library/Caches/Mozilla/updates/Applications/Floorp
echo "Removing $HOME/Library/Caches/Mozilla/updates/Applications/Floorp..."
if [ -d "$HOME/Library/Caches/Mozilla/updates/Applications/Floorp" ]; then
    rm -rf "$HOME/Library/Caches/Mozilla/updates/Applications/Floorp" 2>/dev/null || true
elif [ -f "$HOME/Library/Caches/Mozilla/updates/Applications/Floorp" ]; then
    rm -f "$HOME/Library/Caches/Mozilla/updates/Applications/Floorp" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/*.floorp.plist
echo "Removing $HOME/Library/Preferences/*.floorp.plist..."
if [ -d "$HOME/Library/Preferences/*.floorp.plist" ]; then
    rm -rf "$HOME/Library/Preferences/*.floorp.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/*.floorp.plist" ]; then
    rm -f "$HOME/Library/Preferences/*.floorp.plist" 2>/dev/null || true
fi

# Remove $HOME/Library/Saved Application State/*.floorp.savedState
echo "Removing $HOME/Library/Saved Application State/*.floorp.savedState..."
if [ -d "$HOME/Library/Saved Application State/*.floorp.savedState" ]; then
    rm -rf "$HOME/Library/Saved Application State/*.floorp.savedState" 2>/dev/null || true
elif [ -f "$HOME/Library/Saved Application State/*.floorp.savedState" ]; then
    rm -f "$HOME/Library/Saved Application State/*.floorp.savedState" 2>/dev/null || true
fi

# Remove $HOME/Library/Caches/Mozilla
echo "Removing $HOME/Library/Caches/Mozilla..."
if [ -d "$HOME/Library/Caches/Mozilla" ]; then
    rm -rf "$HOME/Library/Caches/Mozilla" 2>/dev/null || true
elif [ -f "$HOME/Library/Caches/Mozilla" ]; then
    rm -f "$HOME/Library/Caches/Mozilla" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
